lolo:
app ui-data-list "1.0.0"
"DataList — UI factory (1:1 with the @almadar/ui data-list pattern)."
orbital DataListOrbital {
    type DataListLoaded = Event { data : [DataListItem] } "DataList rows finished loading; payload.data holds the collection"
  type DataListFieldsItem = {
    name : string!
    label : string
    icon : icon
    variant : "h3" | "h4" | "body" | "caption" | "badge" | "small" | "progress"
    format : "date" | "currency" | "number" | "boolean" | "percent"
  }
  type DataListColumnsItem = {
    name : string!
    label : string
    icon : icon
    variant : "h3" | "h4" | "body" | "caption" | "badge" | "small" | "progress"
    format : "date" | "currency" | "number" | "boolean" | "percent"
  }
  type DataListItemActionsItem = {
    label : string!
    event : string!
    icon : icon
    variant : "primary" | "secondary" | "ghost" | "danger"
  }
  type DataListError = {
    message : string!
    name : string
    code : string
    stack : string
  }
  type DataListSwipeLeftActionsItem = {
    label : string!
    icon : icon
    variant : "primary" | "secondary" | "danger" | "ghost"
  }
  type DataListSwipeRightActionsItem = {
    label : string!
    icon : icon
    variant : "primary" | "secondary" | "danger" | "ghost"
  }

  entity DataListItem [runtime] {
    id : string!
  }

  trait DataListRender -> @rebindable DataListItem [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (fetch DataListItem { emit: { success: DataListLoaded } })
        (render-ui main {
          dragGroup: @config.dragGroup
          accepts: @config.accepts
          sortable: @config.sortable
          dropEvent: @config.dropEvent
          reorderEvent: @config.reorderEvent
          positionEvent: @config.positionEvent
          dndItemIdField: @config.dndItemIdField
          dndRoot: @config.dndRoot
          entity: @entity
          fields: @config.fields
          columns: @config.columns
          itemActions: @config.itemActions
          maxInlineActions: @config.maxInlineActions
          itemClickEvent: @config.itemClickEvent
          gap: @config.gap
          variant: @config.variant
          groupBy: @config.groupBy
          senderField: @config.senderField
          senderLabelField: @config.senderLabelField
          currentUser: @config.currentUser
          emptyMessage: @config.emptyMessage
          className: @config.className
          isLoading: @config.isLoading
          error: @config.error
          reorderable: @config.reorderable
          swipeLeftEvent: @config.swipeLeftEvent
          swipeLeftActions: @config.swipeLeftActions
          swipeRightEvent: @config.swipeRightEvent
          swipeRightActions: @config.swipeRightActions
          longPressEvent: @config.longPressEvent
          infiniteScroll: @config.infiniteScroll
          loadMoreEvent: @config.loadMoreEvent
          hasMore: @config.hasMore
          pageSize: @config.pageSize
          sortBy: @config.sortBy
          sortDirection: @config.sortDirection
          look: @config.look
          type: data-list
        })
      DataListLoaded -> idle
        (render-ui main {
          dragGroup: @config.dragGroup
          accepts: @config.accepts
          sortable: @config.sortable
          dropEvent: @config.dropEvent
          reorderEvent: @config.reorderEvent
          positionEvent: @config.positionEvent
          dndItemIdField: @config.dndItemIdField
          dndRoot: @config.dndRoot
          entity: @payload.data
          fields: @config.fields
          columns: @config.columns
          itemActions: @config.itemActions
          maxInlineActions: @config.maxInlineActions
          itemClickEvent: @config.itemClickEvent
          gap: @config.gap
          variant: @config.variant
          groupBy: @config.groupBy
          senderField: @config.senderField
          senderLabelField: @config.senderLabelField
          currentUser: @config.currentUser
          emptyMessage: @config.emptyMessage
          className: @config.className
          isLoading: @config.isLoading
          error: @config.error
          reorderable: @config.reorderable
          swipeLeftEvent: @config.swipeLeftEvent
          swipeLeftActions: @config.swipeLeftActions
          swipeRightEvent: @config.swipeRightEvent
          swipeRightActions: @config.swipeRightActions
          longPressEvent: @config.longPressEvent
          infiniteScroll: @config.infiniteScroll
          loadMoreEvent: @config.loadMoreEvent
          hasMore: @config.hasMore
          pageSize: @config.pageSize
          sortBy: @config.sortBy
          sortDirection: @config.sortDirection
          look: @config.look
          type: data-list
        })
    }

    emits {
      @config.reorderEvent -> external {
        id : string
      }
        @description "Event emitted on reorder: UI:{reorderEvent} with { fromIndex, toIndex }"
        @tier "essential"
      @config.itemClickEvent -> external {
        id : string
      }
        @description "When set, the whole row is clickable and emits UI:{itemClickEvent} with { id, row } (action-button clicks stopPropagation so they still win)."
        @tier "essential"
      @config.swipeLeftEvent -> external {
        id : string
      }
        @description "Event emitted on left swipe: UI:{swipeLeftEvent} with { row }"
        @tier "essential"
      @config.swipeRightEvent -> external {
        id : string
      }
        @description "Event emitted on right swipe: UI:{swipeRightEvent} with { row }"
        @tier "essential"
      @config.longPressEvent -> external {
        id : string
      }
        @description "Event emitted on long press: UI:{longPressEvent} with { row }"
        @tier "essential"
      @config.loadMoreEvent -> external {
        id : string
      }
        @description "Event emitted when more items needed: UI:{loadMoreEvent}"
        @tier "essential"
      VIEW -> external {
        id : string
      }
        @description "User opened a record from the list."
        @tier "essential"
      DataListLoaded
        @description "DataList rows finished loading; payload.data holds the collection."
        @synonyms "loaded, fetched, retrieved"
        @tier "essential"
    }

    config {
      dragGroup : string
        @label "Drag Group"
        @description "When set, items in this container are draggable and announce this group as their source"
        @tier "presentation"
      accepts : string
        @label "Accepts"
        @description "When set, the container accepts drops whose dragGroup matches this value (or '*' for any group)"
        @tier "presentation"
      sortable : boolean
        @label "Sortable"
        @description "Enable in-container reorder; items can be dragged to new positions among siblings"
        @tier "presentation"
      dropEvent : string
        @label "Drop Event"
        @description "Bus event fired on cross-container drop. Payload: { id, sourceGroup, targetGroup, newIndex }"
        @tier "presentation"
      reorderEvent : string = "REORDER"
        @label "Reorder Event"
        @description "Event emitted on reorder: UI:{reorderEvent} with { fromIndex, toIndex }"
        @tier "presentation"
      positionEvent : string
        @label "Position Event"
        @description "Bus event fired N times per drop (one per item in affected zones) so the trait can persist new positions for the WHOLE zone, not just the moved item. Payload: { id, position }"
        @tier "presentation"
      dndItemIdField : string
        @label "Dnd Item Id Field"
        @description "Row field used as the @dnd-kit draggable id (default 'id')"
        @tier "presentation"
      dndRoot : boolean
        @label "Dnd Root"
        @description "Mark this container as the DnD root for its subtree — descendant zones share one DndContext (cross-container drag). Use on an outer container whose own items are not draggable."
        @tier "presentation"
      fields : [DataListFieldsItem] = []
        @label "Fields"
        @description "Field definitions for rendering each row. The pattern contract in `@almadar/core/patterns` documents `columns` as the wire-format alias the compiler emits — both names resolve to the same shape here. Pass either."
        @tier "presentation"
      columns : [DataListColumnsItem] = []
        @label "Columns"
        @description "Alias for `fields` — the compiler emits `columns` for field defs."
        @tier "presentation"
      itemActions : [DataListItemActionsItem] = []
        @label "Item Actions"
        @description "Per-item action buttons"
        @tier "presentation"
      maxInlineActions : number
        @label "Max Inline Actions"
        @description "Max inline action buttons before the rest collapse into a '⋯' overflow menu. Omit = all inline."
        @tier "presentation"
      itemClickEvent : string = "ITEM_CLICK"
        @label "Item Click Event"
        @description "When set, the whole row is clickable and emits UI:{itemClickEvent} with { id, row } (action-button clicks stopPropagation so they still win)."
        @tier "presentation"
      gap : "none" | "sm" | "md" | "lg" = none
        @label "Gap"
        @description "Gap between rows"
        @tier "presentation"
      variant : "default" | "card" | "compact" | "message" = default
        @label "Variant"
        @description "Visual variant"
        @tier "presentation"
      groupBy : string
        @label "Group By"
        @description "Group items by a field value (renders section headers between groups)"
        @tier "presentation"
      senderField : string
        @label "Sender Field"
        @description "Field name identifying the sender (used with variant: 'message')"
        @tier "presentation"
      senderLabelField : string
        @label "Sender Label Field"
        @description "Field holding the sender's human-readable name (used with variant: 'message'). Defaults to `senderField`. Set this when `senderField` holds an id — an id-keyed thread otherwise labels bubbles `staff-1` instead of `Sam Staff`."
        @tier "presentation"
      currentUser : string
        @label "Current User"
        @description "Current user identifier; messages matching this value align right (used with variant: 'message')"
        @tier "presentation"
      emptyMessage : string
        @label "Empty Message"
        @description "Message shown when there are no rows. Falls back to the generic 'no items' translation. `TableView` already exposes this; an agenda or an inbox wants to say what 'empty' means in its own words."
        @tier "presentation"
      className : string
        @label "Class Name"
        @description "Additional CSS classes"
        @tier "presentation"
      isLoading : boolean = false
        @label "Is Loading"
        @description "Loading state"
        @tier "presentation"
      error : DataListError
        @label "Error"
        @description "Error state"
        @tier "presentation"
      reorderable : boolean
        @label "Reorderable"
        @description "Enable drag-to-reorder with grip handles"
        @tier "presentation"
      swipeLeftEvent : string = "SWIPE_LEFT"
        @label "Swipe Left Event"
        @description "Event emitted on left swipe: UI:{swipeLeftEvent} with { row }"
        @tier "presentation"
      swipeLeftActions : [DataListSwipeLeftActionsItem] = []
        @label "Swipe Left Actions"
        @description "Actions revealed on left swipe"
        @tier "presentation"
      swipeRightEvent : string = "SWIPE_RIGHT"
        @label "Swipe Right Event"
        @description "Event emitted on right swipe: UI:{swipeRightEvent} with { row }"
        @tier "presentation"
      swipeRightActions : [DataListSwipeRightActionsItem] = []
        @label "Swipe Right Actions"
        @description "Actions revealed on right swipe"
        @tier "presentation"
      longPressEvent : string = "LONG_PRESS"
        @label "Long Press Event"
        @description "Event emitted on long press: UI:{longPressEvent} with { row }"
        @tier "presentation"
      infiniteScroll : boolean
        @label "Infinite Scroll"
        @description "Enable infinite scroll loading"
        @tier "presentation"
      loadMoreEvent : string = "LOAD_MORE"
        @label "Load More Event"
        @description "Event emitted when more items needed: UI:{loadMoreEvent}"
        @tier "presentation"
      hasMore : boolean
        @label "Has More"
        @description "Whether more items are available for infinite scroll"
        @tier "presentation"
      pageSize : number = 5
        @label "Page Size"
        @description "Max items to show before 'Show More' button. Defaults to 5. Set to 0 to disable."
        @tier "presentation"
      sortBy : string
        @label "Sort By"
        @description "Field name to order rows by. Values are compared by their own type — numbers numerically, date-like strings chronologically, everything else alphabetically — never by what the field is called. Empty cells sort last. Unset leaves the incoming order untouched. Orders only the rows already fetched: a collection larger than its `limit` still needs ordering at the data layer."
        @tier "presentation"
      sortDirection : "asc" | "desc" = asc
        @label "Sort Direction"
        @description "Direction for `sortBy`. Defaults to ascending."
        @tier "presentation"
      look : "dense" | "spacious" | "striped" | "borderless" | "card-rows" = dense
        @label "Look"
        @description "Layer 2 visual treatment — mirrors the `entity-table` look enum so data-grid / data-list / entity-table share one knob name from authors."
        @tier "presentation"
    }
  }

  page "/data-list" as DataListPage -> DataListRender
}
